/* Revision tags for photos replaced after shipping. The offline cache keeps
 * files by URL, so a new tag is what makes phones fetch the corrected photo. */
const DEMO_REV = {
  // (none at the moment — the lateral raise moved to a mannequin clip)
};

/* Your own illustrations, one per exercise id, in img/illus/<id>.jpg. Shown in
 * the guide in place of the stock photos (a clip, if there is one, still wins).
 * Bump `rev` when a file is replaced so phones refetch it. */
const DEMO_ILLUS = {
  "ch-smith-incline": { rev: 1 },
  "ch-bench-press": { rev: 1 },
  "ch-low-cable-fly": { rev: 1 },
  "ch-incline-fly": { rev: 1 },
  "ch-incline-fly": { rev: 1 },
  "ch-cable-cross": { rev: 1 },
};
function illusUrl(id) {
  const a = DEMO_ILLUS[id];
  return `img/illus/${id}.jpg${a && a.rev ? `?r=${a.rev}` : ''}`;
}

/* Your own thumbnails for the pictogram box on a card, in img/thumb/<id>.jpg
 * (square, about 240 px). Bump `rev` when a file is replaced. */
const DEMO_THUMBS = {
  "ch-low-cable-fly": { rev: 1 },
  "ch-incline-fly": { rev: 1 },
};
function thumbUrl(id) {
  const a = DEMO_THUMBS[id];
  return `img/thumb/${id}.jpg${a && a.rev ? `?r=${a.rev}` : ''}`;
}
